import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxToast } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [showSuccess, setShowSuccess] = useState(false);

  const emailError = email.length > 0 && !EMAIL_PATTERN.test(email)
    ? 'Введите адрес в формате name@example.com'
    : undefined;

  const isSubmitDisabled = email.length === 0 || Boolean(emailError);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isSubmitDisabled) return;
    setShowSuccess(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)', maxWidth: 420 }}>
      {showSuccess && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`Участник получит приглашение на ${email}`}
          onClose={() => setShowSuccess(false)}
        />
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@example.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
          helperText="На этот адрес придёт ссылка для присоединения к команде"
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton variant="primary" type="submit" disabled={isSubmitDisabled}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

